mapper.select:
SELECT id, user_id AS userId, order_no AS orderNo, total_cent AS totalCent, created_at AS createdAt
FROM shop_order
WHERE status = 'PENDING_PAYMENT'
  AND created_at <= #{olderThan}
  AND created_at >= #{newerThan}
ORDER BY created_at ASC

SELECT COUNT(DISTINCT o.id)
FROM shop_order o
JOIN shop_order_item i ON i.order_id = o.id
WHERE o.user_id = #{userId}
  AND i.product_id = #{productId}
  AND o.id != #{excludeOrderId}
  AND o.status != 'CANCELED'
  AND o.created_at >= #{since}

SELECT COUNT(*) AS purchaseCount, AVG(i.quantity) AS avgQuantity
FROM shop_order_item i
JOIN shop_order o ON o.id = i.order_id
WHERE o.user_id = #{userId}
  AND i.product_id = #{productId}
  AND o.status IN ('PAID', 'SHIPPED', 'COMPLETED')
